import { InjectionToken } from "@angular/core";
import { CreateItemFields, CreateListFields, List, UpdateItemFields, UpdateListFields } from "../models/list.model";
import { Observable } from "rxjs";

export const DATA_REPOSITORY = new InjectionToken<DataRepository>('DataRepository');

export interface DataRepository {
  createItemInList(listId: number, newitem: CreateItemFields): Observable<number>;
  updateItem(id: number, item: UpdateItemFields): Observable<number>;
  deleteItem(id: number): Observable<void>;

  createList(param: CreateListFields): Observable<number>;
  getAllLists(): Observable<List[]>;
  getListById(id: number): Observable<List>;
  updateList(id: number, list: UpdateListFields): Observable<number>;
  deleteList(id: number): Observable<void>;
}
